  function renderInspector(){const root=$('inspector');if(!selected){root.textContent='Select an agent to inspect its decision.';return;}if(replay){const d=(state().decisionRecords||[]).find(x=>x.agent===selected&&x.day===replay.day&&x.tick===replay.tick);root.replaceChildren();const title=document.createElement('strong');title.textContent=`${selected} · day ${replay.day} · tick ${replay.tick}`;const pre=document.createElement('pre');pre.textContent=d?`${d.thought||'No stated thought.'}\n\nAction: ${d.action}${d.target?' → '+d.target:''}`:'No decision recorded for this agent at this tick.';root.append(title,pre);return;}const r=raw.find(x=>x.agent===selected&&x.type==='decision');root.replaceChildren();const title=document.createElement('strong');title.textContent=`${selected} · latest decision`;const pre=document.createElement('pre');if(r){let thought;try{thought=json(r.output).thought;}catch{}pre.textContent=thought||r.output||r.error||'Waiting for a response.';}else pre.textContent='No decision recorded yet. Previous runs did not save raw outputs.';root.append(title,pre);}
